import express, { Request, Response, NextFunction } from 'express';
import { createProxyMiddleware, Options } from 'http-proxy-middleware';
import crypto from 'crypto';

interface User {
  id: string;
  role: 'admin' | 'user' | 'service';
  allowedOrigins: string[];
}

const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex');

const users: Map<string, User> = new Map([
  ['admin-token-001', { id: 'admin1', role: 'admin', allowedOrigins: ['*'] }],
  ['user-token-002', { id: 'user1', role: 'user', allowedOrigins: ['https://api.internal.corp', 'https://data.internal.corp'] }],
  ['svc-token-003', { id: 'svc1', role: 'service', allowedOrigins: ['https://api.internal.corp'] }],
]);

const app = express();

function authenticate(req: Request, res: Response, next: NextFunction): void {
  const token = req.headers['x-auth-token'] as string;
  if (!token || !users.has(token)) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }
  (req as any).user = users.get(token);
  next();
}

function normalizeTarget(input: string): string {
  // Decode any percent-encoding to canonical form
  let decoded = input;
  try {
    decoded = decodeURIComponent(input);
  } catch {
    // If decoding fails, use raw input
  }
  return decoded;
}

function extractOrigin(targetUrl: string): string {
  // Parse the URL and extract scheme + host as the origin
  const normalized = normalizeTarget(targetUrl);
  try {
    const parsed = new URL(normalized);
    return `${parsed.protocol}//${parsed.host}`;
  } catch {
    return '';
  }
}

function verifyIntegrity(target: string, signature: string): boolean {
  const expected = crypto.createHmac('sha256', HMAC_SECRET)
    .update(target)
    .digest('hex');
  return crypto.timingSafeEqual(
    Buffer.from(signature, 'hex'),
    Buffer.from(expected, 'hex')
  );
}

function isOriginAllowed(user: User, origin: string): boolean {
  if (user.role === 'admin') return true;
  if (user.allowedOrigins.includes('*')) return true;
  return user.allowedOrigins.some(allowed => {
    // Case-insensitive comparison of origins
    return allowed.toLowerCase() === origin.toLowerCase();
  });
}

function buildProxyTarget(req: Request): string | null {
  const targetParam = req.query.target as string;
  if (!targetParam) return null;

  // The target parameter is the raw URL the client wants to proxy to
  // We normalize it for origin checking but use the original for proxying
  return targetParam;
}

app.use('/proxy', authenticate, (req: Request, res: Response, next: NextFunction) => {
  const user = (req as any).user as User;
  const target = buildProxyTarget(req);

  if (!target) {
    res.status(400).json({ error: 'Missing target parameter' });
    return;
  }

  const origin = extractOrigin(target);
  if (!origin) {
    res.status(400).json({ error: 'Invalid target URL' });
    return;
  }

  if (!isOriginAllowed(user, origin)) {
    res.status(403).json({ error: 'Target origin not in allowlist', origin });
    return;
  }

  // For non-admin users, verify request integrity to prevent tampering
  if (user.role !== 'admin') {
    const sig = req.headers['x-request-signature'] as string;
    if (sig) {
      // Signature is computed over the normalized target
      const normalized = normalizeTarget(target);
      if (!verifyIntegrity(normalized, sig)) {
        res.status(403).json({ error: 'Invalid request signature' });
        return;
      }
    }
  }

  // Proxy the request to the validated target
  const proxyOptions: Options = {
    target: target,
    changeOrigin: true,
    followRedirects: false,
    secure: true,
    on: {
      proxyReq: (proxyReq) => {
        proxyReq.removeHeader('x-auth-token');
        proxyReq.removeHeader('x-request-signature');
        proxyReq.setHeader('X-Forwarded-For', req.ip || '127.0.0.1');
      },
      error: (err, _req, _res) => {
        console.error('Proxy error:', err.message);
      }
    }
  };

  const proxy = createProxyMiddleware(proxyOptions);
  proxy(req, res, next);
});

app.get('/health', (_req: Request, res: Response) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

const PORT = parseInt(process.env.PORT || '3000', 10);
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Proxy server listening on 127.0.0.1:${PORT}`);
});

export default app;
